      "Studentmedical.java": "class Studentmedical\n{\npublic static void main(String args[]) throws Exception\n\n{\nSystem.out.println(\"enter the total num of class\");\nint n1=new java.util.Scanner(System.in).nextInt();\nSystem.out.println(\"enter the total num of attended\");\nint n2=new java.util.Scanner(System.in).nextInt();\nSystem.out.println(\"enter the total num of medical\");\nint x= System.in.read();\nchar ch=(char)x;\nint per=(n2*100)/n1;\nif(per>=75)\nSystem.out.println(\"allowed\");\nelse if(ch=='Y' || ch=='y')\nSystem.out.println(\"allowed to sit exam \" + per);\nelse\nSystem.out.println(\"not allowed\");\n}\n}",
      "Task1.java": "class Task1\n{\npublic static void main(String args[])\n{\nint charge=0;\nSystem.out.println(\"enter bike number\");\nString bno=new java.util.Scanner(System.in).nextLine();\nSystem.out.println(\"enter customer name\");\nString name=new java.util.Scanner(System.in).nextLine();\nSystem.out.println(\"enter number of days\");\nint days =new java.util.Scanner(System.in).nextInt();\n\nif(days\u003c=5)\n{\ncharge=500*days;\n}\nelse if (days>5 && days\u003c=10)\n{\ncharge=2500+400*(days-5);\n}\nelse if (days>10)\n{\ncharge=2500+2000+200*(days-10);\n}\n\nSystem.out.println(\"Bike no: \" + bno);\nSystem.out.println(\"Name of customer: \" + name);\nSystem.out.println(\"Number of Days: \" + days);\nSystem.out.println( \"Charges: \" + charge);\n\n// System.out.print(\"bike no\" + \"\\t\\t\\t\" + \" Customer\" + \" \\t\\t\\t\\ \" + \"Days\" + \"Charges\" + \"\\t\\t\\t\");\n// System.out.print(\"\");\n// System.out.print(bno + \"\\t\\t\");\n// System.out.print(name + \"\\t\\t\");\n// System.out.print(days + \"\\t\\t\");\n// System.out.print(charge + \"\\t\\t\");\n\n}\n}",
