      "P58.java": "class P58\n{\n    public static void main(String args[])\n    {\n        int n = 5;\n\n        for(int i = 1; i \u003c= n; i++)\n        {\n            int x;\n\n            if(i == 1)\n                x = 1;\n            else if(i == 5)\n                x = 1;\n            else\n                x = 0;\n\n            for(int j = 1; j \u003c= n - i + 1; j++)\n            {\n                System.out.print(x);\n\n                if(x == 1)\n                    x = 0;\n                else\n                    x = 1;\n            }\n\n            System.out.println();\n        }\n    }\n}",
      "P6.java": "class P6\n{\npublic static void main(String args[])\n{\nint i,j,rows;\n\nSystem.out.printf(\"Enter the num: \");\nrows=new java.util.Scanner(System.in).nextInt();\n\nfor(i=1; i\u003c=rows; i++)\n{\nfor(j=1; j\u003c=rows; j++)\n{\n\tif(i%2==0){\n\tSystem.out.print(\"0\");\n\t}\n\telse{\n\t\tSystem.out.print(\"1\");\n\t}\n}\nSystem.out.println(\" \");\n}\n}\n}\n// 11111\n// 00000\n// 11111\n// 00000\n// 11111",
      "P7.java": "class P7\n{\npublic static void main(String args[])\n{\nint i,j,rows;\nSystem.out.printf(\"Enter the num: \");\nrows=new java.util.Scanner(System.in).nextInt();\n\nfor(i=1; i\u003c=rows; i++)\n{\nfor(j=i; j\u003c=i+4; j++)\n{\nSystem.out.print(j);\n}\nSystem.out.println(\" \");\n\n\n}\n}\n}\n// 12345\n// 23456\n// 34567\n// 45678\n// 56789",
      "P8.java": "class P8\n{\npublic static void main(String args[])\n{\nint i,rows;\nchar ch='A';\nSystem.out.printf(\"Enter the num: \");\nrows=new java.util.Scanner(System.in).nextInt();\n\nfor(i=1; i\u003c=rows; i++)\n{\nfor(ch='A'; ch\u003c='E'; ch++)\n{\nSystem.out.print(ch);\n}\nSystem.out.println(\" \");\n}\n}\n}\n// ABCDE\n// ABCDE\n// ABCDE\n// ABCDE\n// ABCDE\n",
      "P9.java": "class P9\n{\npublic static void main(String args[])\n{\nint i,j,rows;\n\nSystem.out.printf(\"Enter the num: \");\nrows=new java.util.Scanner(System.in).nextInt();\n\nfor(i=1; i\u003c=rows; i++)\n{\nfor(j=1; j\u003c=rows; j++)\n{\n\tif(i%2==0){\n\tSystem.out.print(i);\n\t}\n\telse{\n\t\tSystem.out.print(\"*\");\n\t}\n}\nSystem.out.println(\" \");\n}\n}\n}\n// *****\n// 22222\n// *****\n// 44444\n// *****",
      "Ppt.java": "public class Ppt {\n    public static void main(String[] args) {\n\n        int[] space = {0, 1, 6, 1, 4};\n\n        for (int i = 0; i \u003c 5; i++) {\n\n            for (int j = 0; j \u003c space[i]; j++)\n                System.out.print(\" \");\n\n            for (int j = 0; j \u003c= i; j++)\n                System.out.print(\"*\");\n\n            System.out.println();\n        }\n    }\n}",
