      "Practice04Home.java": "class Practice04Home\n{\npublic static void main(String args[])\n{\nint i,j;\nfor(i=1; i\u003c=2; i++){\n	for(j=1; j\u003c=4; j++){\n		if(i==1 && j==3 || i==2 && j>1){\n			System.out.print(\"*\");\n		}else{System.out.print(\" \");}		\n	}\n     System.out.println();\n}\n\nfor(i=1; i\u003c=4; i++){\n	for(j=1; j\u003c=5; j++){\n		if(j%2!=0 && j!=3){\n			System.out.print(\"@\");\n		} else if(j==3 || i>=2){\n			System.out.print(\"*\");\n		} else{System.out.print(\" \");}\n	}\n	System.out.println();\n}\n\n// for(i=1; i\u003c=5; i++){\n	// System.out.print(\"*\");\n// }\n// System.out.println();\n\nfor(i=1; i\u003c=3; i++){\n	for(j=1; j\u003c=5; j++){\n		if(j==2 || j==3 || j==4){\n		System.out.print(\"*\");\n		}\n		else{System.out.print(\" \");}\n}\nSystem.out.println();\n}\n}\n}",
