      "Practice08Home.java": "class Practice08Home\n{\npublic static void main(String args[])\n{\nint i,j,sp;\nint n=5,x=1;\nSystem.out.println(); \n\nfor(i=1; i\u003c=3; i++){\n for(sp=1; sp\u003c=5-i+4; sp++){\n  System.out.print(\" \");\n }\n  for(j=1; j\u003c=x; j++){\n   System.out.print(\"*\");\n   }\n   x+=2;\n   System.out.println();\n   }\n   \n   for(i=1; i\u003cn-1; i++){\n	for(j=1; j\u003c=11; j++){\n		if(j==7 || j==11){\n		 System.out.print(\"@\");\n	}else\n	{\n	 System.out.print(\" \");\n	}\n	}\n	System.out.println();\n   }\n   \n   x=5;\n   int s=4,s1=1;\n   for(i=1; i\u003c=3; i++){\n	for(sp=4-s+1; sp>=1; sp--){\n		System.out.print(\" \");\n	}\n	for(j=1; j\u003c=x; j++){\n	 System.out.print(\"*\"); \n	}\n	for(sp=3-s1+1; sp>=1; sp--){\n		if(sp==3 && i==1)System.out.print(\"@\");\n		else System.out.print(\" \");\n	}\n	for(sp=5-s+1; sp>=1; sp--){\n		if(sp==1 && i==1)System.out.print(\"@\");\n	    else System.out.print(\" \");	\n	}\n	for(j=1; j\u003c=x; j++){\n	 System.out.print(\"*\"); \n	}\n	s1--;\n	s--;\n    x-=2;\n	System.out.println();\n   }  \n}\n}",
      "Practice08_01Home.java": "class Practice08_01Home\n{\npublic static void main(String args[])\n{\nint i,j,x=1;\nfor(i=3; i>=1; i--){\n for(int sp=1; sp\u003c=i+3-1; sp++){\n  System.out.print(\" \");\n   }\n   for(j=1; j\u003c=x; j++){\n    System.out.print(x);\n	}\n	x+=2;\n	System.out.println();\n	}\n	\n	for(i=1; i\u003c=4; i++){\n		for(int sp=1; sp\u003c=3; sp++){\n			System.out.print(\" \");\n		}\n		for(j=1; j\u003c=5; j++){\n			if(j==1 || j==5)\n				System.out.print(\"$\");\n			else System.out.print(\" \");\n		}\n		System.out.println();\n	}\n	\n	x=3;\n	for(i=3; i>=1; i--){\n		for(int sp=1; sp\u003c=3-i; sp++){\n			System.out.print(\" \");\n		}\n		for(j=1; j\u003c=x; j++){\n			System.out.print(\"&\");\n		}\n	    if(i==3)System.out.print(\"@\");	\n		x-=2;\n		\n		for(int sp=1; sp\u003c=3; sp++){\n		System.out.print(\" \");	\n	    }\n	    if(i==3)System.out.print(\"@\");	\n	    x+=2;\n		for(j=1; j\u003c=x; j++){\n			System.out.print(\"&\");\n		}\n		x-=2;\n		\n		System.out.println();\n	}\n	\n	\n	\n	}\n	}",
