      "JComboEx2.java": "import java.awt.BorderLayout;\nimport java.awt.Container;\nimport java.awt.event.*;\n\nimport javax.swing.JComboBox;\nimport javax.swing.JFrame;\n\n class JComboEx2 extends JFrame \n{\n  public JComboEx2() \n{\n    this.setDefaultCloseOperation(EXIT_ON_CLOSE);\n\n    String[] sList = new String[] { \"Spring\", \"Summer\", \"Fall\", \"Winter\" };\n    JComboBox seasons = new JComboBox(sList);\n\n    seasons.addItemListener(new MyItem());\n\n    Container contentPane = this.getContentPane();\n    contentPane.add(seasons, BorderLayout.CENTER);\n  }\n\n  public static void main(String[] args) {\n    JComboEx2 com = new JComboEx2();\n\n   com.setSize(300,300);\n\n   com.setVisible(true);\n  }\n}\nclass MyItem  implements ItemListener\n{\n\npublic  void itemStateChanged(ItemEvent  e)\n{\n      Object item = e.getItem();\n      if (e.getStateChange() == ItemEvent.SELECTED) {\n        // Item has been selected\n        System.out.println(item + \"  has  been  selected\");\n      } else if (e.getStateChange() == ItemEvent.DESELECTED) {\n        // Item has been deselected\n        System.out.println(item + \"  has  been  deselected\");\n      }\n    }\n}\n\n\n\n\n",
      "MyJTable.java": "import java.awt.*;\nimport java.awt.event.*;\nimport javax.swing.*;\npublic class MyJTable extends JFrame {\n\n  String[] headings    = {\"name\"  ,\"add\",\"salary\"};\nString items[][]={\n		{\"amit\",\"delhi\",\"1000\"},\n		{\"amit\",\"delhi\",\"1000\"},\n		{\"amit\",\"delhi\",\"1000\"},\n		{\"amit\",\"delhi\",\"1000\"},\n		{\"amit\",\"delhi\",\"1000\"},\n		{\"amit\",\"delhi\",\"1000\"},\n	};\n  public MyJTable() {\n    super(\"Table example\");  \nJTable jt=new JTable(items,headings);\nJScrollPane jp=new  JScrollPane(jt);\n    add(jp);\nsetSize(400,400);\n//pack();\nsetVisible(true);\n  }\n  public static void main (String args[]) \n{\n new MyJTable();\n      }\n    }\n    \n\n\n\n",
      "awtevent/AdapterClassDemo.java": "import java.awt.*;\nimport java.awt.event.*;\nclass AdapterClassDemo implements ActionListener \n{\nFrame f;\nButton b,b1;\nTextField tf;\n	AdapterClassDemo(String s)\n	{	\n		f=new Frame(s);\n		b=new Button(\"ok\");\n		b1=new Button(\"cancel\");\n		b.setBounds(20,100,40,40);\n		b1.setBounds(20,180,40,40);\n	     \n		b.addActionListener(this);\n		b1.addActionListener(this);\n\n\n		f.add(b);\n		f.add(b1);\n		tf=new TextField();\ntf.addKeyListener(new KeyEventListener());\n		tf.setBounds(20,40,100,40);\n		f.add(tf);\nf.addWindowListener(new WindowEventListener());\nf.addMouseListener(new MouseEventListener(this));\n		f.setLayout(null);\n		f.setSize(400,400);\n		f.setVisible(true);\n\n	}\n\npublic void actionPerformed(ActionEvent e)\n{\nSystem.out.println(\"ap\");\nif(e.getSource()==b)\ntf.setText(\"ok\");\nif(e.getSource()==b1)\n{\ntf.setText(\"cancel\");\n}\n}\npublic static void main(String s[])\n{\nnew AdapterClassDemo(\"event demo\");\n}\n}\n                          //implements  WindowListener \nclass WindowEventListener extends WindowAdapter\n{\npublic void windowClosing(WindowEvent e1)\n{\nSystem.exit(0);\n}\n\n}\n                         //implements  MouseListener \nclass MouseEventListener extends MouseAdapter\n{\nAdapterClassDemo t;\nMouseEventListener(AdapterClassDemo f)\n{\nthis.t=f;\n}\npublic void mouseClicked(MouseEvent e1)\n{\nt.tf.setText(\"mouseevent\");\nt.f.setBackground(Color.RED);\n}\n}\n                       //implements  KeyListener   \nclass KeyEventListener extends KeyAdapter\n{\npublic void keyTyped(KeyEvent e)\n{\n\nSystem.out.println(e.getKeyChar());   \n\n}\n}\n\n\n\n\n\n//tf.addKeyListener(new KeyEventListener());\n\n\n\n//f.addWindowListener(new WindowEventListener());\n//f.addMouseListener(new MouseEventListener(this));\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
