      "awtevent/InnerListener.java": "import java.awt.*;\nimport java.awt.event.*;\nclass InnerListener implements ActionListener \n{\nFrame f;\nButton b,b1;\nTextField tf;\n	InnerListener(String s)\n	{	\n		f=new Frame(s);\n		b=new Button(\"ok\");\n		b1=new Button(\"cancel\");\n		b.setBounds(20,100,40,40);\n		b1.setBounds(20,180,40,40);\n	     \n		b.addActionListener(this);\n		b1.addActionListener(new ActionListener()\n		{\n			public void actionPerformed(ActionEvent e)\n{\n\ntf.setText(\"InnerListener\");\n\n}\n			\n		});\n\n\n		f.add(b);\n		f.add(b1);\n		tf=new TextField();\n\n		tf.setBounds(20,40,100,40);\n		f.add(tf);\n\n		f.setLayout(null);\n		f.setSize(400,400);\n		f.setVisible(true);\n\n	}\n\npublic void actionPerformed(ActionEvent e)\n{\nSystem.out.println(\"ap\");\nif(e.getSource()==b)\ntf.setText(\"ok\");\nif(e.getSource()==b1)\n{\ntf.setText(\"cancel\");\n}\n}\npublic static void main(String s[])\n{\nnew InnerListener(\"event demo\");\n}\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
      "awtevent/OuterListener.java": "import java.awt.*;\nimport java.awt.event.*;\nclass OuterListener implements ActionListener \n{\nFrame f;\nButton b,b1;\nTextField tf;\n	OuterListener(String s)\n	{	\n		f=new Frame(s);\n		b=new Button(\"ok\");\n		b1=new Button(\"cancel\");\n		b.setBounds(20,100,40,40);\n		b1.setBounds(20,180,40,40);\n	     Outer o=new Outer(this);\n		b.addActionListener(this);\n		b1.addActionListener(o);\n		\n\n		f.add(b);\n		f.add(b1);\n		tf=new TextField();\n\n		tf.setBounds(20,40,100,40);\n		f.add(tf);\n\n		f.setLayout(null);\n		f.setSize(400,400);\n		f.setVisible(true);\n\n	}\n\npublic void actionPerformed(ActionEvent e)\n{\nSystem.out.println(\"ap\");\nif(e.getSource()==b)\ntf.setText(\"ok\");\nif(e.getSource()==b1)\n{\ntf.setText(\"cancel\");\n}\n}\npublic static void main(String s[])\n{\nnew OuterListener(\"event demo\");\n}\n}\n\n\n\n\n\nclass Outer implements ActionListener \n{\nOuterListener f;\nOuter(OuterListener f)\n{\nthis.f=f;\n}\npublic void actionPerformed(ActionEvent e)\n{\n	System.out.println(\"Outer's ap\");\nif(e.getSource()==f.b)\nf.tf.setText(\"lalu\");\nif(e.getSource()==f.b1)\nf.tf.setText(\"rabari\");\n}\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
      "awtevent/SameClassListener.java": "import java.awt.*;\nimport java.awt.event.*;\nclass SameClassListener implements ActionListener \n{\nFrame f;\nButton b,b1;\nTextField tf;\n	SameClassListener(String s)\n	{	\n		f=new Frame(s);\n		b=new Button(\"ok\");\n		b1=new Button(\"cancel\");\n		b.setBounds(20,100,40,40);\n		b1.setBounds(20,180,40,40);\n	     \n		b.addActionListener(this);\n		b1.addActionListener(this);\n\n\n		f.add(b);\n		f.add(b1);\n		tf=new TextField();\n\n		tf.setBounds(20,40,100,40);\n		f.add(tf);\n\n		f.setLayout(null);\n		f.setSize(400,400);\n		f.setVisible(true);\n\n	}\n\npublic void actionPerformed(ActionEvent e)\n{\nSystem.out.println(\"ap\");\nif(e.getSource()==b)\ntf.setText(\"ok - i understand\");\nif(e.getSource()==b1)\n{\ntf.setText(\"cancel - no i can't\");\n}\n}\npublic static void main(String s[])\n{\nnew SameClassListener(\"event demo\");\n}\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
      "awtevent/Sum.java": "import java.awt.*;\nimport java.awt.event.*;\nclass Sum implements ActionListener \n{\nFrame f;\nButton b;\nTextField tf,tf1,tf2;\n	Sum()\n	{\n	f=new Frame(\"Sum\");\n		b=new Button(\"Sum\");\n		\n		b.addActionListener(this);\n		\n		\n		tf=new TextField();\n		tf1=new TextField();\n		tf2=new TextField();\n		f.add(tf);\n		f.add(tf1);\n		f.add(tf2);\n		f.add(b);\n		\n		f.setLayout(new FlowLayout());\n		f.setSize(400,400);\n		f.setVisible(true);\n\n	}\npublic void actionPerformed(ActionEvent e)\n{\nString s1=tf.getText();\nString s2=tf1.getText();\nint n1=Integer.parseInt(s1);\nint n2=Integer.parseInt(s2);\nint n3=n1+n2;\nString  z=String.valueOf(n3);\ntf2.setText(z);\n\n}\npublic static void main(String s[])\n{\nnew Sum();\n\n}\n\n}\n\n//Float  f=Float.valueOf(s1);\n//float f1=f.floatValue();\n\n",
