      "layout/BLayout.java": "import java.awt.*;\nimport java.awt.event.*;\nimport javax.swing.*;\nclass BLayout \n{\nJFrame f;\nJButton b[];\n\nBLayout(String s)\n{\n f=new JFrame(s);\nb=new JButton[5];\nString s1[]={\"north\",\"south\",\"east\",\"west\",\"center\"};\nString x[]={BorderLayout.NORTH,BorderLayout.SOUTH,BorderLayout.EAST,BorderLayout.WEST,BorderLayout.CENTER};\nfor(int i=0;i\u003cb.length;i++)\n{\nb[i]=new JButton(s1[i]);\nf.add(b[i],x[i]);\n}\nf.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);\nf.setSize(400,400);\nf.setVisible(true);\n}\n\npublic static void main(String s[])\n{\n\nnew BLayout(\"BorderLayout\");\n\n}\n}\n\n\n//Container c=f.getContentPane();\n//c.add(jt);\n//c.add(b);\n//c.add(b1);\n//jp=new JPanel();\n//cl=new CardLayout();\n//jp.setLayout(cl);\n\n\n",
